async def act(page):
    """
    Reduce the product price by 10% on the current Magento product edit page.
    Steps:
    - Open the Prices tab
    - Read the current Price field
    - Compute a 10% reduction
    - Fill the Price field with the new value
    - Save the product
    """
    import re

    # 1) Open the Prices tab. Use a substring name match for the "Prices" tab/link.
    # The accessibility tree shows a link whose name ends with "Prices", so matching "Prices" is robust.
    await page.get_by_role("link", name="Prices").click()

    # 2) Wait for the Price textbox to appear. The Prices tab typically provides a textbox with accessible name "Price".
    price_field = page.get_by_role("textbox", name="Price")
    await price_field.wait_for(state="visible", timeout=5000)

    # 3) Read the current value.
    raw_value = await price_field.input_value()

    # 4) Parse the numeric value from the input. Strip currency symbols, commas, whitespace.
    numeric_str = re.sub(r"[^0-9.\-]", "", raw_value or "")
    if numeric_str == "":
        # If we can't parse a value, raise an informative error so the test harness knows something went wrong.
        raise RuntimeError(f"Could not determine current price from input value: '{raw_value}'")

    try:
        current_price = float(numeric_str)
    except Exception as e:
        raise RuntimeError(f"Failed to parse price '{numeric_str}' from raw input '{raw_value}': {e}")

    # 5) Compute the reduced price (10% off), round to 2 decimals as typical for prices.
    new_price = round(current_price * 0.9, 2)

    # 6) Fill the Price field with the new value. Use a standard two-decimal format.
    formatted = f"{new_price:.2f}"
    await price_field.fill(formatted)

    # 7) Save the product. The top action button is labelled "Save".
    # According to the instructions, this click may navigate away, so it should be the last action.
    await page.get_by_role("button", name="Save").click()

